import type { BuiltInGuide } from "./guide-library";

const refs = (label: string, url: string) => [{ label, url }];

type Seed = {
  slug: string; parentSlug: string; category: string; title: string; summary: string;
  expansion: string; level: string; audience: string; imageUrl: string; order: number;
  prep: string[]; steps: string[]; source: [string, string]; notes?: string[];
};

const fullArticle = (s: Seed): BuiltInGuide => ({
  slug: s.slug, parentSlug: s.parentSlug, type: "article", category: s.category,
  title: s.title, summary: s.summary, expansion: s.expansion, level: s.level,
  audience: s.audience, imageUrl: s.imageUrl, order: s.order,
  tags: [s.category.toLowerCase(), s.expansion.toLowerCase(), s.level],
  content: [
    "## Requirements and preparation", ...s.prep.map((x) => "- [ ] " + x), "",
    "## Complete step-by-step route", ...s.steps.map((x, i) => (i + 1) + ". " + x), "",
    "## Completion checks", "| Check | Required result |", "|---|---|",
    "| Active objective | The named quest is visible in Journal before farming; earlier items may not count. |",
    "| Correct class/job | Accept, complete class-specific objectives, and turn in on the named class/job. |",
    "| Equipment state | Equip the evolving item only when requested; unequip it if the exchange NPC refuses it. |",
    "| Quantity/quality | Match the exact item, amount, HQ icon, or collectability threshold in the duty list. |",
    "| Inventory | Keep a normal inventory slot and the relevant Armoury Chest slot open. |", "",
    "## Final checklist", "- [ ] Confirm the next objective before spending currency.",
    "- [ ] Keep the old stage until the replacement is visibly received.",
    "- [ ] Record chosen attributes before resetting them.",
    "- [ ] Unlock replicas or appearance rewards before discarding a stage.", "",
    "## Troubleshooting", "- **No marker:** finish the prerequisite, switch to the required class/job, and carry the prior stage.",
    "- **No drop:** confirm the quest is active and the source is named by its current duty list.",
    "- **Grey exchange:** unequip the item, repair it, and make inventory/Armoury Chest room.",
    ...(s.notes || []).map((x) => "- " + x),
  ].join("\n"), references: refs(s.source[0], s.source[1]),
});

const societyTier = (slug: string, title: string, level: string, expansion: string, links: string[], order: number): BuiltInGuide => ({
  slug, parentSlug: "tribal-quests", type: "collection", category: "Allied Society Tier", title,
  summary: "A complete level-specific route with rank timing, unlock gates, vendors, and one full guide per society.",
  expansion, level, audience: "Combat, Crafting & Gathering", tags: ["allied society", "reputation", level],
  imageUrl: "/guides/allied-society-bases.svg", order,
  content: ["## Tier rules", "- **12 daily allowances** are shared account-wide; a society normally offers three random quests.",
    "- Rank quests consume no allowance. When reputation caps, finish the blue rank quest before another daily; reputation cannot spill through the cap.",
    "- Accept and finish synced objectives on the eligible job receiving experience. A job change can hide nodes, recipes, items, or interactions.",
    "- New rank pools join earlier pools, so a high-rank character can still receive an early daily.", "",
    "## Societies in this tier", ...links.map((x) => "- " + x), "",
    "## Daily route", "1. Check Character → Reputation for a full bar.",
    "2. Accept all three on the intended job; open every Journal map and group objectives by area.",
    "3. Put supplied Key Items, mount actions, and duty actions on a temporary hotbar.",
    "4. Craft only Special Recipes; HQ is required only when the duty list shows the HQ icon.",
    "5. Turn in before reset, spend currency before its cap, complete any new blue quest, and reopen the vendor.",
    "", "## Rank pacing", "Friendly-era societies generally use Friendly → Trusted → Respected → Honored → Sworn → Bloodsworn. Exact reputation totals differ by expansion, and extra same-day quests can appear after a rank-up. The individual pages list the actual rank stories and reward tiers."].join("\n"),
  references: refs("Allied Society allowances and reputation", "https://ffxiv.consolegameswiki.com/wiki/Allied_Society_Quests"),
});

const collectTier = (slug: string, title: string, level: string, expansion: string, hubs: string, books: string, order: number): BuiltInGuide => fullArticle({
  slug, parentSlug: "collectables-scrips", category: "Collectables & Scrips", title,
  summary: "The complete unlock, appraisal, scrip, Master Recipe, folklore, gear, and timed-node route for this tier.",
  expansion, level, audience: "Crafting & Gathering", imageUrl: "/guides/collectables-route.svg", order,
  prep: ["Complete Inscrutable Tastes in Foundation to unlock collectables, appraisers, and scrip exchanges.",
    "Reach and attune the tier's hubs: " + hubs + ".", "Unlock flying before building timed-node routes.",
    "Put Collect, Scrutiny, Scour/Meticulous, and current quality actions on accessible hotbars."],
  steps: ["Open Timers → Rowena's House of Splendors and select the exact class. The live list supplies the current item, minimum rating, rewards, and limits.",
    "Crafted collectables: open the collectable/Special Recipe, synthesize it, and raise quality into the required collectability band. Ordinary HQ rules do not apply.",
    "Miner/botanist: arrive during the node window, reveal the named item, use appraisal actions to meet the displayed rating, then Collect. Stop spending GP once the next reward band is unreachable.",
    "Fisher: enable Collect before casting and use the named fishing hole, bait, time, and weather. Keep only catches meeting the threshold.",
    "Turn in at any Collectable Appraiser. Test one item before making a batch and confirm its actual scrip return.",
    "Buy permanent unlocks before consumables: " + books + ". Use every purchased folklore tome from inventory; merely buying it does not reveal nodes.",
    "Then buy required tools/gear and materia. Old red/blue/yellow scrip advice is obsolete; use the current exchange categories shown in game.",
    "For a missing legendary node, verify the correct regional tome, its use from inventory, Eorzean time, weather, perception requirement, and exact zone."],
  source: ["Official collectables guide", "https://na.finalfantasyxiv.com/lodestone/playguide/contentsguide/collectables/"],
});

type Client = { slug: string; parent: string; name: string; level: string; expansion: string; location: string; unlock: string; prereq: string; story: string; glamour: string; order: number };
const clientArticle = (c: Client): BuiltInGuide => fullArticle({
  slug: c.slug, parentSlug: c.parent, category: "Custom Delivery Client", title: c.name,
  summary: "A client-specific unlock, weekly-item, satisfaction, crafting, gathering, fishing, reward, and appearance guide.",
  expansion: c.expansion, level: c.level, audience: "Crafting & Gathering", imageUrl: "/guides/custom-deliveries-route.svg", order: c.order,
  prep: ["Unlock Custom Deliveries through Go West, Craftsman.", "Keep six of the shared twelve weekly allowances available.",
    "Travel to " + c.location + ".", "Complete: " + c.prereq + "."],
  steps: ["Accept **" + c.unlock + "** and finish the introduction to add the client to Duty → Timers → Custom Deliveries.",
    "Open the client in Timers before producing anything. It shows this week's exact item, collectability bands, bonus, satisfaction, and allowances.",
    "Crafting: buy only the client-specific material from the nearby supplier, open Special Recipes → Custom Deliveries, and make one test item. Quality becomes collectability.",
    "Mining/botany: select the requested item in Timers/Gathering Log, use the named node, and meet the rating before Collect.",
    "Fishing: enable Collect, use the Fishing Log's hole and bait, and retain catches meeting the displayed band.",
    "Deliver up to six. A bonus request pays extra scrips and satisfaction; prioritize it only if its rating is practical.",
    "Complete each blue satisfaction follow-up: " + c.story + ". A missing final scene usually means one is waiting.",
    "Appearance at maximum satisfaction: " + c.glamour + ". Continue delivering afterward for scrips, experience, and achievements."],
  source: [c.name + " delivery reference", "https://ffxiv.consolegameswiki.com/wiki/Custom_Deliveries"],
  notes: ["Requested items rotate with rank and reset, so the in-game Timers entry is the exact current-week item list.",
    "Market items with similar names do not replace the client's quest-specific supplier materials."],
});

const customTier = (slug: string, title: string, level: string, expansion: string, links: string[], order: number): BuiltInGuide => ({
  slug, parentSlug: "custom-deliveries", type: "collection", category: "Custom Delivery Tier", title,
  summary: "A complete tier plan plus one full unlock-to-rank-five guide for every client.", expansion, level,
  audience: "Crafting & Gathering", tags: ["custom deliveries", "weekly", level], imageUrl: "/guides/custom-deliveries-route.svg", order,
  content: ["## Weekly rules", "- You have **12 deliveries per week account-wide** and may give at most **6 to one client**.",
    "- Requested items and bonuses are in Duty → Timers. Quality/rating becomes collectability; higher bands pay more.",
    "- Deliver on the class receiving experience. Max-satisfaction clients remain valid for scrip farming.", "",
    "## Clients", ...links.map((x) => "- " + x), "", "## Two-client plan",
    "1. Reserve six allowances for the client whose story or appearance controls you need.",
    "2. Use the other six on a bonus client or the class needing experience.",
    "3. Produce one test item, verify its rating in Timers, then make the batch.",
    "4. Finish newly opened blue follow-up quests before leaving the area."].join("\n"),
  references: refs("Custom Delivery rules", "https://ffxiv.consolegameswiki.com/wiki/Custom_Deliveries"),
});

