const relic = (slug: string, parentSlug: string, title: string, expansion: string, level: string, order: number, prep: string[], steps: string[], source: string): BuiltInGuide => fullArticle({
  slug, parentSlug, category: title.split(":")[0] + " Stage", title,
  summary: "A self-contained stage guide with exact prerequisites, materials, duties, hand-ins, repeat rules, and failure checks.",
  expansion, level, audience: "Combat",
  imageUrl: expansion === "Heavensward" || expansion === "Endwalker" ? "/guides/relic-stage-route.svg" : "/guides/field-operation-route.svg",
  order, prep, steps, source: [title + " reference", source],
});

